import csv
import datetime
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

DEPOT_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
FACTORS = {"kg": Decimal(1), "g": Decimal("0.001"), "lb": Decimal("0.45392"), "oz": Decimal("0.02837")}
MONTHS = {m: i + 1 for i, m in enumerate("jan feb mar apr may jun jul aug sep oct nov dec".split())}

COLUMNS = {
    "east": {"id", "type", "shipped", "gross", "net", "status", "note"},
    "harbor": {"rec", "ref", "date", "weight", "state"},
    "lakeside": {"id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"},
    "river": {"t", "ref", "shipped", "weight", "status"},
    "west": {"id", "typ", "shipped", "weight", "status", "note"},
}
DELIMS = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
FIELDS = {
    "east": dict(id="id", type="type", date="shipped", weight="gross", status="status"),
    "harbor": dict(id="ref", type="rec", date="date", weight="weight", status="state"),
    "lakeside": dict(id="id", type="kind", date="shipped", weight="gross_kg", status="status"),
    "river": dict(id="ref", type="t", date="shipped", weight="weight", status="status"),
    "west": dict(id="id", type="typ", date="shipped", weight="weight", status="status"),
}
BASE_DATE = {"east": "YMD", "harbor": "iso", "lakeside": "iso", "river": "MM/DD/YYYY", "west": "DD.MM.YYYY"}
DECIMAL_COMMA = {"west"}

LAYOUTS = {
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), date=(10, 17), weight=(17, 25), status=(25, 26),
                datefmt="ydoy", unit="g", scale=Decimal(1)),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), date=(10, 18), weight=(18, 26), status=(26, 27),
                datefmt="ymd8", unit="kg", scale=Decimal("0.01")),
    "FW3": dict(length=41, id=(0, 9), date=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25),
                datefmt="ydoy", unit="lb", scale=Decimal("0.1")),
}
SOUTH_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}
HARBOR_STATUS = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled", "RET": "returned", "HLD": "held"}


def read_bytes(path):
    with open(path, "rb") as handle:
        data = handle.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be")
    match = re.search(rb"^#[ \t]*charset[ \t]*:[ \t]*([\w.-]+)", data[:2000], re.M | re.I)
    if match:
        return data.decode(match.group(1).decode("ascii"))
    return data.decode("utf-8")


def norm_id(text):
    match = re.fullmatch(r"\s*SH\W*0*(\d+)\s*", text or "", re.I)
    if not match:
        return None
    return int(match.group(1))


def norm_type(text):
    text = (text or "").strip().lower()
    if text.startswith("v"):
        return "void"
    if text.startswith(("c", "a")):
        return "correction"
    return "new"


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", (text or "").strip().lower())


def is_counted(status):
    return status in ("delivered", "delivered_late")


def parse_date(text, form):
    text = (text or "").strip()
    if not text:
        return None
    match = re.fullmatch(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d(?::?\d\d)?)?", text, re.I)
    if match:
        year, month, day, hour, minute, second, zone = match.groups()
        moment = datetime.datetime(int(year), int(month), int(day), int(hour), int(minute), int(second or 0))
        if zone and zone.upper() != "Z":
            sign = 1 if zone[0] == "+" else -1
            digits = zone[1:].replace(":", "")
            offset = datetime.timedelta(hours=int(digits[:2]), minutes=int(digits[2:] or 0))
            moment -= sign * offset
        return moment.date()
    form = (form or "").strip()
    lowered = form.lower()
    match = re.fullmatch(r"(\d{4})[-/.](\d\d?)[-/.](\d\d?)", text)
    if match:
        return datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    match = re.fullmatch(r"(\d\d?)\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})", text)
    if match:
        return datetime.date(int(match.group(3)), MONTHS[match.group(2).lower()], int(match.group(1)))
    match = re.fullmatch(r"(\d\d?)\.(\d\d?)\.(\d{4})", text)
    if match:
        return datetime.date(int(match.group(3)), int(match.group(2)), int(match.group(1)))
    match = re.fullmatch(r"(\d\d?)([-/])(\d\d?)\2(\d{4})", text)
    if match:
        first, second, year = int(match.group(1)), int(match.group(3)), int(match.group(4))
        if lowered in ("mm/dd/yyyy", "mdy", "mm-dd-yyyy"):
            return datetime.date(year, first, second)
        return datetime.date(year, second, first)
    if re.fullmatch(r"\d+(\.\d+)?", text):
        if lowered == "serial" or not re.fullmatch(r"\d{8}", text):
            return datetime.date(1899, 12, 30) + datetime.timedelta(days=int(float(text)))
        return datetime.date(int(text[:4]), int(text[4:6]), int(text[6:8]))
    raise ValueError("unparsable date %r" % text)


def parse_number(text, decimal_comma):
    text = text.strip().replace(" ", "")
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Decimal(text)


def weight_kg(text, field_unit, row_unit, directive_unit, base_unit, decimal_comma):
    text = (text or "").strip()
    match = re.fullmatch(r"([-+\d.,\s]+?)\s*([A-Za-z]+)", text)
    value_unit = None
    if match:
        text, value_unit = match.group(1), match.group(2).lower()
    number = parse_number(text, decimal_comma)
    unit = value_unit or field_unit or row_unit or directive_unit or base_unit
    return number * FACTORS[unit.lower()]


def clean_unit(text):
    match = re.match(r"\s*([A-Za-z]+)", text or "")
    unit = match.group(1).lower() if match else None
    return unit if unit in FACTORS else None


def make_record(rtype, number, status=None, date=None, kg=None):
    return dict(type=rtype, number=number, status=status, date=date, kg=kg)


def logical_lines(text, quoting):
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    pending = None
    for line in lines:
        if line.endswith("\r"):
            line = line[:-1]
        if pending is not None:
            pending += "\n" + line
            if pending.count('"') % 2 == 0:
                yield pending
                pending = None
            continue
        if line.startswith("#"):
            yield line
            continue
        if quoting and line.count('"') % 2 == 1:
            pending = line
            continue
        yield line
    if pending is not None:
        yield pending


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    columns = COLUMNS[depot]
    names = FIELDS[depot]
    decimal_comma = depot in DECIMAL_COMMA
    seq = None
    directives = {}
    header = None
    records = []
    for line in logical_lines(text, delim == ","):
        if line.startswith("#"):
            match = re.match(r"#\s*([^:=]+?)\s*:\s*(.*?)\s*$", line)
            if match:
                directives[match.group(1).lower()] = match.group(2)
                if match.group(1).lower() == "seq" and seq is None:
                    seq = int(match.group(2))
            else:
                match = re.search(r"\bseq\s*=\s*(\d+)", line)
                if match and seq is None:
                    seq = int(match.group(1))
            continue
        if not line.strip():
            continue
        if delim == ",":
            fields = next(csv.reader([line], delimiter=",", quotechar='"'))
        else:
            fields = line.split(delim)
        stripped = [field.strip() for field in fields]
        if stripped and all(field.lower() in columns for field in stripped):
            header = [field.lower() for field in stripped]
            continue
        if header is None:
            continue
        row_unit = None
        weight_index = header.index(names["weight"]) if names["weight"] in header else None
        if len(fields) == len(header) + 1 and weight_index is not None:
            row_unit = clean_unit(fields[weight_index + 1])
            del fields[weight_index + 1]
        if len(fields) != len(header):
            continue
        row = dict(zip(header, fields))
        number = norm_id(row.get(names["id"]))
        if number is None:
            continue
        rtype = norm_type(row.get(names["type"]))
        if rtype == "void":
            records.append(make_record("void", number))
            continue
        status = norm_status(row.get(names["status"]))
        if depot == "harbor":
            status = HARBOR_STATUS.get(row.get(names["status"], "").strip().upper(), status)
        date = parse_date(row.get(names["date"]), directives.get("dates") or directives.get("date format") or BASE_DATE[depot])
        field_unit = None
        if names["weight"].endswith("_kg"):
            field_unit = "kg"
        directive_unit = clean_unit(directives.get("unit") or directives.get("weight unit"))
        kg = weight_kg(row.get(names["weight"]), field_unit, row_unit, directive_unit, "kg", decimal_comma)
        records.append(make_record(rtype, number, status, date, kg))
    return seq, records


def parse_south(text):
    seq = None
    layout = None
    records = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if line.startswith("\x0c") or not line.strip():
            continue
        if line.startswith("#"):
            match = re.match(r"#LAYOUT\s+(\w+)", line)
            if match:
                layout = match.group(1)
                continue
            match = re.match(r"#SEQ\s+(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        spec = LAYOUTS.get(layout)
        if spec is None or len(line) != spec["length"]:
            spec = None
            for candidate in LAYOUTS.values():
                if candidate["length"] == len(line):
                    spec = candidate
            if spec is None:
                continue

        def field(name):
            start, end = spec[name]
            return line[start:end]

        number = norm_id(field("id"))
        if number is None:
            continue
        rtype = norm_type(field("type"))
        if rtype == "void":
            records.append(make_record("void", number))
            continue
        if spec["datefmt"] == "ydoy":
            raw = field("date")
            date = datetime.date(int(raw[:4]), 1, 1) + datetime.timedelta(days=int(raw[4:]) - 1)
        else:
            date = parse_date(field("date"), "YMD")
        kg = Decimal(int(field("weight"))) * spec["scale"] * FACTORS[spec["unit"]]
        records.append(make_record(rtype, number, SOUTH_STATUS.get(field("status").strip().upper(), ""), date, kg))
    return seq, records


def parse_north(text):
    seq = None
    records = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        value = json.loads(line)
        for obj in value if isinstance(value, list) else [value]:
            if not isinstance(obj, dict):
                continue
            if "meta" in obj and "id" not in obj:
                if seq is None and isinstance(obj["meta"], dict) and "seq" in obj["meta"]:
                    seq = int(obj["meta"]["seq"])
                continue
            number = norm_id(str(obj.get("id", "")))
            if number is None:
                continue
            rtype = norm_type(obj.get("kind"))
            if rtype == "void":
                records.append(make_record("void", number))
                continue
            kg = None
            for key, raw in obj.items():
                match = re.fullmatch(r"weight_(\w+)", key)
                if match:
                    kg = Decimal(str(raw)) * FACTORS[match.group(1).lower()]
            date = parse_date(obj.get("shipped_at"), "iso")
            records.append(make_record(rtype, number, norm_status(obj.get("status")), date, kg))
    return seq, records


def parse_central(data):
    root = ET.fromstring(data)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = clean_unit(root.get("weight-unit"))
    records = []
    for element in root.iter("shipment"):
        number = norm_id(element.get("id"))
        if number is None:
            continue
        rtype = norm_type(element.get("type"))
        if rtype == "void":
            records.append(make_record("void", number))
            continue
        weight = element.find("weight")
        unit = clean_unit(weight.get("unit")) if weight is not None else None
        kg = weight_kg(weight.text, None, None, unit or root_unit, "kg", False)
        shipped = element.get("shipped")
        child = element.find("shipped")
        if child is not None and child.text:
            shipped = child.text
        status = element.find("status")
        records.append(make_record(rtype, number, norm_status(status.text if status is not None else ""),
                                   parse_date(shipped, "iso"), kg))
    return seq, records


def parse_file(depot, path):
    data = read_bytes(path)
    if depot == "central":
        return parse_central(data)
    text = decode(data)
    if depot == "south":
        return parse_south(text)
    if depot == "north":
        return parse_north(text)
    return parse_delimited(depot, text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        seq, records = parse_file(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, files in exports.items():
        files.sort(key=lambda item: (item[0], item[1]))
        state = {}
        for _, _, records in files:
            for record in records:
                number = record["number"]
                if record["type"] == "new":
                    if number in state:
                        resends += 1
                    else:
                        state[number] = record
                elif record["type"] == "correction":
                    state[number] = record
                    corrections += 1
                else:
                    state.pop(number, None)
                    corrections += 1
        current[depot] = state

    def rank(depot):
        return DEPOT_ORDER.index(depot) if depot in DEPOT_ORDER else len(DEPOT_ORDER)

    owners = {}
    for depot in sorted(current, key=rank):
        for number in current[depot]:
            owners.setdefault(number, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)

    depot_totals = {depot: [0, Decimal(0)] for depot in sorted(exports)}
    month_totals = {}
    for number, depots in owners.items():
        depot = depots[0]
        record = current[depot][number]
        if not is_counted(record["status"]):
            continue
        depot_totals[depot][0] += 1
        depot_totals[depot][1] += record["kg"]
        key = "%04d-%02d" % (record["date"].year, record["date"].month)
        entry = month_totals.setdefault(key, [0, Decimal(0)])
        entry[0] += 1
